    const lineEnd = combined.indexOf(0x0a, lineStart);
    if (lineEnd < 0) break;
    const line = combined.subarray(lineStart, lineEnd);
    lineStart = lineEnd + 1;
    if (line.length === 0) continue;
    try {
      const frame = JSON.parse(line.toString('utf8')) as ManagedHostRunOutputFrame;
